const legacy2023PageByRoute = new Map(
  legacy2023Pages.map((page) => [page.route, page])
);

export function getLegacy2023Page(route: string): Legacy2023Page {
  const normalizedRoute = route.endsWith('/') ? route : `${route}/`;
  const page = legacy2023PageByRoute.get(normalizedRoute);

  if (!page) {
    throw new Error(`Missing PyCon HK 2023 page: ${route}`);
  }

  return page;
}
